use anyhow::{Context, Result};
use ed25519_dalek::{Signer, SigningKey, Verifier, VerifyingKey};
use std::path::{Path, PathBuf};

pub struct KeyPair {
    signing_key: SigningKey,
}

impl KeyPair {
    pub fn generate() -> Self {
        let mut csprng = rand::rngs::OsRng;
        Self {
            signing_key: SigningKey::generate(&mut csprng),
        }
    }

    pub fn from_bytes(secret: &[u8; 32]) -> Self {
        Self {
            signing_key: SigningKey::from_bytes(secret),
        }
    }

    pub fn sign(&self, data: &[u8]) -> String {
        let sig = self.signing_key.sign(data);
        hex::encode(&sig.to_bytes())
    }

    pub fn public_key_hex(&self) -> String {
        hex::encode(self.signing_key.verifying_key().as_bytes())
    }

    pub fn secret_bytes(&self) -> &[u8; 32] {
        self.signing_key.as_bytes()
    }

    pub fn save(&self, path: &Path) -> Result<()> {
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent)?;
        }
        std::fs::write(path, self.signing_key.as_bytes())
            .context("failed to write signing key")?;
        let pub_path = path.with_extension("pub");
        std::fs::write(&pub_path, self.signing_key.verifying_key().as_bytes())
            .context("failed to write public key")?;

        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            std::fs::set_permissions(path, std::fs::Permissions::from_mode(0o600))?;
        }

        Ok(())
    }

    pub fn load(path: &Path) -> Result<Self> {
        let bytes = std::fs::read(path).context("failed to read signing key")?;
        let secret: [u8; 32] = bytes
            .try_into()
            .map_err(|_| anyhow::anyhow!("invalid key length"))?;
        Ok(Self::from_bytes(&secret))
    }
}

pub fn verify(public_key_hex: &str, data: &[u8], signature_hex: &str) -> bool {
    let Ok(pk_bytes) = hex::decode(public_key_hex) else {
        return false;
    };
    let Ok(pk_arr): Result<[u8; 32], _> = pk_bytes.try_into() else {
        return false;
    };
    let Ok(verifying_key) = VerifyingKey::from_bytes(&pk_arr) else {
        return false;
    };
    let Ok(sig_bytes) = hex::decode(signature_hex) else {
        return false;
    };
    let Ok(sig_arr): Result<[u8; 64], _> = sig_bytes.try_into() else {
        return false;
    };
    let signature = ed25519_dalek::Signature::from_bytes(&sig_arr);
    verifying_key.verify(data, &signature).is_ok()
}

pub fn keys_dir() -> PathBuf {
    dirs::data_dir()
        .or_else(|| dirs::home_dir().map(|h| h.join(".local/share")))
        .expect("neither data_dir nor home_dir available — cannot store signing keys")
        .join("codeflow")
        .join("keys")
}

pub fn load_or_generate() -> Result<KeyPair> {
    let dir = keys_dir();
    let key_path = dir.join("signing.key");

    match KeyPair::load(&key_path) {
        Ok(kp) => return Ok(kp),
        Err(_) => {}
    }

    if let Some(parent) = key_path.parent() {
        std::fs::create_dir_all(parent)?;
    }

    let kp = KeyPair::generate();

    // Atomic create-or-fail to prevent TOCTOU race between concurrent hook processes
    match std::fs::OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(&key_path)
    {
        Ok(mut f) => {
            use std::io::Write;
            f.write_all(kp.secret_bytes())?;
            drop(f);

            let pub_path = key_path.with_extension("pub");
            std::fs::write(&pub_path, kp.signing_key.verifying_key().as_bytes())?;

            #[cfg(unix)]
            {
                use std::os::unix::fs::PermissionsExt;
                std::fs::set_permissions(&key_path, std::fs::Permissions::from_mode(0o600))?;
            }

            Ok(kp)
        }
        Err(e) if e.kind() == std::io::ErrorKind::AlreadyExists => {
            // Another process won the race — load their key
            KeyPair::load(&key_path)
        }
        Err(e) => Err(e.into()),
    }
}

mod hex {
    pub fn encode(bytes: &[u8]) -> String {
        bytes.iter().map(|b| format!("{:02x}", b)).collect()
    }

    pub fn decode(s: &str) -> Result<Vec<u8>, String> {
        if s.len() % 2 != 0 {
            return Err("odd length".to_string());
        }
        (0..s.len())
            .step_by(2)
            .map(|i| u8::from_str_radix(&s[i..i + 2], 16).map_err(|e| e.to_string()))
            .collect()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_generate_and_sign_verify() {
        let kp = KeyPair::generate();
        let data = b"test message";
        let sig = kp.sign(data);
        let pk = kp.public_key_hex();
        assert!(verify(&pk, data, &sig));
    }

    #[test]
    fn test_wrong_data_fails_verify() {
        let kp = KeyPair::generate();
        let sig = kp.sign(b"original");
        let pk = kp.public_key_hex();
        assert!(!verify(&pk, b"tampered", &sig));
    }

    #[test]
    fn test_wrong_key_fails_verify() {
        let kp1 = KeyPair::generate();
        let kp2 = KeyPair::generate();
        let sig = kp1.sign(b"data");
        assert!(!verify(&kp2.public_key_hex(), b"data", &sig));
    }

    #[test]
    fn test_save_and_load() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("test.key");
        let kp = KeyPair::generate();
        kp.save(&path).unwrap();
        let loaded = KeyPair::load(&path).unwrap();
        assert_eq!(kp.secret_bytes(), loaded.secret_bytes());
    }

    #[test]
    fn test_from_bytes_roundtrip() {
        let kp = KeyPair::generate();
        let bytes = *kp.secret_bytes();
        let kp2 = KeyPair::from_bytes(&bytes);
        assert_eq!(kp.public_key_hex(), kp2.public_key_hex());
    }

    #[test]
    fn test_invalid_verify_inputs() {
        assert!(!verify("not-hex", b"data", "not-hex"));
        assert!(!verify("aabb", b"data", "ccdd"));
        assert!(!verify("", b"data", ""));
    }

    #[test]
    fn test_hex_roundtrip() {
        let original = vec![0u8, 1, 255, 128, 64];
        let encoded = hex::encode(&original);
        let decoded = hex::decode(&encoded).unwrap();
        assert_eq!(original, decoded);
    }
}

use anyhow::Result;
use codeflow_core::dedup::DedupCache;
use codeflow_core::events::EventBuffer;
use codeflow_core::filter::{FilterPipeline, FilterResult};
use codeflow_core::proto;
use codeflow_core::tracking::{SavingsLayer, TrackingDb, TrackingEvent};
use std::io::Write;
use std::process::Command;
use std::time::Instant;

use crate::paths;

pub fn execute(command_args: &[String]) -> Result<()> {
    if command_args.is_empty() {
        anyhow::bail!("No command specified");
    }

    let program = &command_args[0];
    let args = &command_args[1..];

    let start = Instant::now();
    let cmd_output = run_command(program, args)?;
    let raw_output = &cmd_output.combined;
    let session_id = codeflow_core::util::session_id();
    let project_dir = std::env::current_dir()
        .unwrap_or_default()
        .to_string_lossy()
        .to_string();

    let result = match compress(raw_output, program, args, &session_id, &project_dir) {
        Ok(r) => r,
        Err(e) => {
            tracing::warn!("compression failed, passing through: {}", e);
            print_output(raw_output);
            propagate_exit(cmd_output.exit_code);
            return Ok(());
        }
    };

    let latency_ms = start.elapsed().as_secs_f64() * 1000.0;
    tracing::debug!(
        command = program,
        input_len = result.filter.input_len,
        output_len = result.filter.output_len,
        dedup_hit = result.dedup_hit,
        latency_ms = latency_ms,
        "wrap complete"
    );

    if result.dedup_hit {
        if let Some(summary) = &result.dedup_summary {
            print_output(summary);
        } else {
            print_output(&result.filter.output);
        }
    } else {
        print_output(&result.filter.output);
    }

    propagate_exit(cmd_output.exit_code);
    Ok(())
}

struct WrapResult {
    filter: FilterResult,
    dedup_hit: bool,
    dedup_summary: Option<String>,
}

fn compress(
    raw_output: &str,
    program: &str,
    args: &[String],
    session_id: &str,
    project_dir: &str,
) -> Result<WrapResult> {
    let data_dir = paths::data_dir();
    std::fs::create_dir_all(&data_dir)?;
    let db_path = paths::db_path();

    let filters_dir = paths::filters_dir();
    let pipeline = FilterPipeline::load_from_dir(&filters_dir).unwrap_or_else(|e| {
        tracing::debug!("filter load failed, using empty pipeline: {}", e);
        FilterPipeline::new()
    });

    let filter_result = pipeline.apply(program, &args.iter().map(|s| s.to_string()).collect::<Vec<_>>(), raw_output);

    let dedup_cache = DedupCache::open(&db_path, session_id)?;
    let content_to_check = &filter_result.output;
    let fake_mtime = 0u64; // commands dedup on content hash only, mtime irrelevant
    let dedup_result = dedup_cache.lookup(
        &format!("cmd:{}:{}", program, args.join(" ")),
        fake_mtime,
        content_to_check,
    )?;

    let tokens_saved_compress = if filter_result.filter_applied {
        codeflow_core::util::estimate_tokens(filter_result.input_len) - codeflow_core::util::estimate_tokens(filter_result.output_len)
    } else {
        0
    };

    let tracking = TrackingDb::open(&db_path)?;

    if filter_result.filter_applied && tokens_saved_compress > 0 {
        tracking.record(&TrackingEvent {
            command: program.to_string(),
            input_tokens: codeflow_core::util::estimate_tokens(filter_result.input_len) as u64,
            output_tokens: codeflow_core::util::estimate_tokens(filter_result.output_len) as u64,
            tokens_saved: tokens_saved_compress as u64,
            layer: SavingsLayer::Compression,
            project: project_dir.to_string(),
            session_id: session_id.to_string(),
        })?;
    }

    if dedup_result.cache_hit {
        tracking.record(&TrackingEvent {
            command: program.to_string(),
            input_tokens: codeflow_core::util::estimate_tokens(filter_result.output_len) as u64,
            output_tokens: 0,
            tokens_saved: dedup_result.tokens_saved,
            layer: SavingsLayer::Dedup,
            project: project_dir.to_string(),
            session_id: session_id.to_string(),
        })?;
    }

    if let Ok(event_buf) = EventBuffer::open(&db_path) {
        let event = proto::Event {
            id: uuid::Uuid::new_v4().to_string(),
            timestamp_ms: chrono::Utc::now().timestamp_millis(),
            session_id: session_id.to_string(),
            project_dir: project_dir.to_string(),
            command: format!("{} {}", program, args.join(" ")),
            event_type: if dedup_result.cache_hit && dedup_result.tokens_saved > tokens_saved_compress as u64 {
                proto::EventType::Dedup as i32
            } else if filter_result.filter_applied {
                proto::EventType::Compression as i32
            } else {
                proto::EventType::Unspecified as i32
            },
            compression: Some(proto::CompressionEvent {
                input_bytes: filter_result.input_len as u64,
                output_bytes: filter_result.output_len as u64,
                input_tokens: codeflow_core::util::estimate_tokens(filter_result.input_len) as u64,
                output_tokens: codeflow_core::util::estimate_tokens(filter_result.output_len) as u64,
                tokens_saved: tokens_saved_compress as u64,
                filter_name: program.to_string(),
                compression_level: "default".to_string(),
                latency_ms: 0.0,
            }),
            dedup: if dedup_result.cache_hit {
                Some(proto::DedupEvent {
                    content_hash: dedup_result.content_hash.clone(),
                    cache_hit: true,
                    tokens_saved: dedup_result.tokens_saved,
                    file_path: String::new(),
                    latency_ms: 0.0,
                })
            } else {
                None
            },
            provenance: None,
            cost: None,
            governance: None,
            quality: None,
        };
        let _ = event_buf.append(&event);
    }

    Ok(WrapResult {
        filter: filter_result,
        dedup_hit: dedup_result.cache_hit,
        dedup_summary: dedup_result.summary,
    })
}

struct CommandOutput {
    combined: String,
    exit_code: Option<i32>,
}

fn run_command(program: &str, args: &[String]) -> Result<CommandOutput> {
    let output = Command::new(program)
        .args(args)
        .output()
        .map_err(|e| anyhow::anyhow!("failed to execute {}: {}", program, e))?;

    let mut combined = String::new();
    if !output.stdout.is_empty() {
        combined.push_str(&String::from_utf8_lossy(&output.stdout));
    }
    if !output.stderr.is_empty() {
        if !combined.is_empty() {
            combined.push('\n');
        }
        combined.push_str(&String::from_utf8_lossy(&output.stderr));
    }
    Ok(CommandOutput {
        combined,
        exit_code: output.status.code(),
    })
}

fn print_output(text: &str) {
    let stdout = std::io::stdout();
    let mut handle = stdout.lock();
    let _ = handle.write_all(text.as_bytes());
    if !text.ends_with('\n') {
        let _ = handle.write_all(b"\n");
    }
    let _ = handle.flush();
}

fn propagate_exit(exit_code: Option<i32>) {
    if let Some(code) = exit_code {
        if code != 0 {
            std::process::exit(code);
        }
    }
}

#[cfg(test)]
mod tests {
    use codeflow_core::dedup::DedupCache;
    use codeflow_core::filter::{
        CommandMatch, FilterConfig, FilterPipeline, StripLinesRule,
    };
    use tempfile::TempDir;

    fn make_pipeline_with_strip(command: &str, strip_pattern: &str) -> FilterPipeline {
        let mut pipeline = FilterPipeline::new();
        pipeline.add_config(FilterConfig {
            command: CommandMatch {
                name: command.to_string(),
                args_contain: vec![],
            },
            strip_ansi: Some(false),
            replace: vec![],
            match_output: None,
            strip_lines: vec![StripLinesRule {
                pattern: strip_pattern.to_string(),
            }],
            truncate_lines: None,
            head_tail: None,
            max_lines: None,
            on_empty: None,
        });
        pipeline
    }

    // --- filter-only path ---

    #[test]
    fn test_filter_reduces_output() {
        // Pipeline strips "Downloading" lines — noisy cargo-like output should shrink
        let pipeline = make_pipeline_with_strip("cargo", r"^Downloading");
        let raw = "Downloading foo v1.0\nDownloading bar v2.0\nCompiling mylib v0.1\nFinished in 3.2s";
        let result = pipeline.apply("cargo", &[], raw);
        assert!(result.filter_applied);
        assert!(
            result.output_len < result.input_len,
            "filtered output ({}) should be smaller than input ({})",
            result.output_len,
            result.input_len
        );
        assert!(!result.output.contains("Downloading"));
        assert!(result.output.contains("Compiling"));
    }

    #[test]
    fn test_filter_passthrough_when_no_match() {
        // Pipeline exists for "cargo" but we apply it to "npm" — passthrough
        let pipeline = make_pipeline_with_strip("cargo", r"^Downloading");
        let raw = "some output that would normally be filtered";
        let result = pipeline.apply("npm", &[], raw);
        assert!(!result.filter_applied);
        assert_eq!(result.output, raw);
    }

    // --- fail-open: empty pipeline passes through ---

    #[test]
    fn test_empty_pipeline_passthrough() {
        // When filter config is missing/broken, FilterPipeline::new() is used
        // which is exactly what compress() falls back to on error.
        let pipeline = FilterPipeline::new();
        let raw = "important output that must not be lost";
        let result = pipeline.apply("anything", &[], raw);
        assert!(!result.filter_applied, "empty pipeline should not filter");
        assert_eq!(result.output, raw, "output should be unchanged");
        assert_eq!(result.input_len, result.output_len);
    }

    // --- dedup cache within compress pipeline ---

    #[test]
    fn test_dedup_cache_miss_on_first_lookup() {
        let dir = TempDir::new().unwrap();
        let db_path = dir.path().join("test.db");
        let cache = DedupCache::open(&db_path, "wrap-test-session").unwrap();

        let result = cache.lookup("cmd:cargo:build", 0, "build output content").unwrap();
        assert!(!result.cache_hit);
        assert_eq!(result.tokens_saved, 0);
    }

    #[test]
    fn test_dedup_cache_hit_on_second_lookup_same_session() {
        let dir = TempDir::new().unwrap();
        let db_path = dir.path().join("test.db");
        let cache = DedupCache::open(&db_path, "wrap-test-session").unwrap();

        let content = "build finished successfully\nerror count: 0";
        // First lookup: miss, stores entry
        let r1 = cache.lookup("cmd:cargo:build", 0, content).unwrap();
        assert!(!r1.cache_hit);

        // Second lookup with same mtime=0 and same content: hit
        let r2 = cache.lookup("cmd:cargo:build", 0, content).unwrap();
        assert!(r2.cache_hit);
        assert!(r2.tokens_saved > 0);
        assert!(r2.summary.is_some());
    }

    #[test]
    fn test_dedup_cache_different_sessions_no_hit() {
        let dir = TempDir::new().unwrap();
        let db_path = dir.path().join("test.db");

        let cache1 = DedupCache::open(&db_path, "session-a").unwrap();
        cache1.lookup("cmd:git:status", 0, "nothing to commit").unwrap();
        drop(cache1);

        // New session — same content, same mtime, but different session_id → miss
        let cache2 = DedupCache::open(&db_path, "session-b").unwrap();
        let r = cache2.lookup("cmd:git:status", 0, "nothing to commit").unwrap();
        assert!(!r.cache_hit, "cross-session lookup must not hit");
    }
}

