pub fn by_pr(&self, pr_ref: &str, days: Option<i64>) -> Result<Vec<CostBreakdown>> {
    let cutoff_ms = cutoff_ms(days);
    let mut stmt = self.conn.prepare(
        "SELECT model_id as grp, SUM(cost_usd), SUM(input_tokens), SUM(output_tokens), COUNT(*)
         FROM cost_records WHERE timestamp_ms >= ?1 AND pr_ref = ?2
         GROUP BY grp ORDER BY SUM(cost_usd) DESC",
    )?;
    let rows = stmt.query_map(params![cutoff_ms, pr_ref], |row| {
        Ok(CostBreakdown {
            key: row.get::<_, String>(0).unwrap_or_default(),
            cost_usd: row.get(1)?,
            input_tokens: row.get::<_, i64>(2)? as u64,
            output_tokens: row.get::<_, i64>(3)? as u64,
            record_count: row.get::<_, i64>(4)? as u64,
        })
